    <CollapsibleInfoGrid
      defaultExpanded
      title={t('deliveryPlan:tabs.generalInfo', { defaultValue: 'Thông tin chung' })}
      className="border border-border/60 shadow-xs mb-4"
      gridClassName="grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-x-6 gap-y-4"
    >
      <InfoField
        label={t('deliveryPlan:fields.code', { defaultValue: 'Mã kế hoạch' })}
        value={
          data.code ? (
            <span className="font-mono font-bold text-primary">{data.code}</span>
