            '—'
          )
        }
      />

      <InfoField
        label={t('deliveryPlan:fields.name', { defaultValue: 'Tên kế hoạch' })}
        value={data.name}
        className="md:col-span-2"
      />

      <InfoField
        label={t('deliveryPlan:fields.planningDate', { defaultValue: 'Ngày lập' })}
        value={data.planningDate ? format(new Date(data.planningDate), 'dd/MM/yyyy') : '—'}
      />

      <InfoField
        label={t('deliveryPlan:fields.period', { defaultValue: 'Thời gian thực hiện' })}
        value={
          data.startDate || data.endDate
