            : '—'
        }
      />

      <InfoField
        label={t('deliveryPlan:fields.status', { defaultValue: 'Trạng thái quy trình' })}
        value={<WorkItemStatusBadge status={workItem?.workItemStatus} variant="badge" />}
      />

      <InfoField
        label={t('deliveryPlan:fields.organization', { defaultValue: 'Đơn vị / Phòng ban' })}
        value={data.organizationNameSnapshot}
      />

      <InfoField
        label={t('deliveryPlan:fields.responsibleEmp', { defaultValue: 'Người phụ trách' })}
        value={data.responsibleEmpNameSnapshot}
      />

      {data.projectNameSnapshot && (
        <InfoField
          label={t('deliveryPlan:fields.project', { defaultValue: 'Dự án' })}
          value={data.projectNameSnapshot}
        />
      )}

      {data.salesOrderNameSnapshot && (
        <InfoField
          label={t('deliveryPlan:fields.salesOrder', { defaultValue: 'Đơn hàng' })}
          value={data.salesOrderNameSnapshot}
        />
      )}

      <InfoField
        label={t('deliveryPlan:fields.progress', { defaultValue: 'Tiến độ giao hàng' })}
        value={
          <div className="flex items-center gap-2">
            <span className="font-bold text-slate-800 dark:text-slate-200">
              {data.totalCompletedQuantity ?? 0} / {data.totalTargetQuantity ?? 0}
            </span>
            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-bold bg-emerald-50 text-emerald-700 border border-emerald-200">
              {data.totalTargetQuantity
