                    Math.round(
                      ((data.totalCompletedQuantity ?? 0) / data.totalTargetQuantity) * 100,
                    ),
                    100,
                  )
                : 0}%
            </span>
          </div>
        }
      />

      <InfoField
        label={t('deliveryPlan:fields.cost', { defaultValue: 'Chi phí' })}
        value={
          <div className="text-sm font-semibold text-slate-800 dark:text-slate-200">
            {data.actualCost
              ? `${new Intl.NumberFormat('vi-VN').format(Number(data.actualCost))} đ`
              : '0 đ'}
