              </span>
            ) : null}
          </div>
        }
      />

      {data.description && (
        <InfoField
          label={t('deliveryPlan:fields.description', { defaultValue: 'Mô tả / Ghi chú' })}
          value={
            <div className="text-muted-foreground bg-muted/30 p-2.5 rounded-md border border-border/50 text-xs leading-relaxed">
              {data.description}
            </div>
          }
          className="col-span-full"
        />
      )}
    </CollapsibleInfoGrid>

    {/* ── Tabs: Chi tiết kiện hàng & Biểu đồ Gantt ── */}
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-border/60 shadow-xs overflow-hidden min-w-0 w-full">
      <div className="px-4 py-2.5 border-b border-border/60 bg-muted/30 flex items-center justify-between gap-4 flex-wrap">
        <Tabs
          value={activeTab}
          onValueChange={(val: any) => setActiveTab(val as 'details' | 'gantt')}
          className="w-auto"
        >
          <TabsList className="bg-muted/60 p-0.5 h-8">
            <TabsTrigger
              value="details"
              className="h-7 px-3 text-xs font-semibold data-[state=active]:bg-background data-[state=active]:shadow-xs flex items-center gap-1.5"
            >
              <List className="w-3.5 h-3.5 text-emerald-600" />
              {t('deliveryPlan:tabs.details', { defaultValue: 'Chi tiết kiện hàng' })}
              {details.length > 0 && (
                <span className="ml-1 text-[11px] px-1.5 py-0.2 bg-muted rounded-full font-mono">
                  {details.length}
                </span>
              )}
            </TabsTrigger>
            <TabsTrigger
              value="gantt"
              className="h-7 px-3 text-xs font-semibold data-[state=active]:bg-background data-[state=active]:shadow-xs flex items-center gap-1.5"
            >
              <CalendarDays className="w-3.5 h-3.5 text-indigo-500" />
              {t('deliveryPlan:tabGantt', { defaultValue: 'Tiến độ Gantt' })}
            </TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      <div className="p-4 min-w-0 overflow-x-auto">
        {activeTab === 'details' ? (
          <DeliveryPlanTable
            readOnly
            details={details}
            onOpenStageModal={(detailId, stage) => {
              setEditingStage({ detailId, stage });
            }}
          />
        ) : (
          <DeliveryGanttView planId={id} plans={data ? [data] : []} />
        )}
      </div>
    </div>
  </div>

