    const getVal = (field: keyof ILocationAddress): string => {
      let val = '';
      if (value && typeof value === 'object') {
        val = (value[field] as string) || '';
      }
      if (!val && formContext) {
        const path = resolveFieldPath(field);
        val = formContext.getValues(path) || '';
      }
      return val;
    };

    setDraft({
      countryId: getVal('countryId'),
      countryCodeSnapshot: getVal('countryCodeSnapshot'),
      countryNameSnapshot: getVal('countryNameSnapshot'),
      provinceId: getVal('provinceId'),
      provinceCodeSnapshot: getVal('provinceCodeSnapshot'),
      provinceNameSnapshot: getVal('provinceNameSnapshot'),
      wardId: getVal('wardId'),
      wardCodeSnapshot: getVal('wardCodeSnapshot'),
      wardNameSnapshot: getVal('wardNameSnapshot'),
      streetAddress: getVal('streetAddress'),
    });
  }
}, [open, targetPrefix, value]);

// Auto-default to Vietnam (or defaultCountryCode) if no country is configured yet
useEffect(() => {
  if (!open || !defaultCountryCode) return;
  if (userInteractedWithCountryRef.current) return;

  if (!draft.countryId) {
    const rawList = countryDropdownQuery.data?.data ?? countryDropdownQuery.data;
    const list = Array.isArray(rawList) ? rawList : [];
    if (list.length === 0) return;

    const targetCode = defaultCountryCode.trim().toUpperCase();
    const matched: any = list.find((c: any) => {
      const code = (c.code || c.countryCode || c.value || '').trim().toUpperCase();
      const name = (c.name || c.label || c.commonName || '').trim().toLowerCase();
      return (
        code === targetCode ||
        (targetCode === 'VN' &&
          (code === 'VNM' || name === 'việt nam' || name === 'vietnam' || name.includes('việt nam')))
      );
    });

    if (matched) {
      setDraft((prev) => {
        if (prev.countryId) return prev;
        return {
          ...prev,
