} from '@shared/enums/servicedesk/delivery-plan-status.enum';
import {
  Badge,
  Button,
  Combobox,
  FormControl,
  FormField,
  FormItem,
  Input,
  NumericInput,
  TableRow,
  TableCell,
} from '@shared/ui';

import {
  type TDeliveryPlanDetailForm,
  type TDeliveryPlanForm,
  type TDeliveryPlanStageForm,
} from './delivery-plan-copy-stages-popover';
import {
  DeliveryPlanBatchOperationsDialog,
  type BatchOperationsPayload,
} from './delivery-plan-batch-operations-dialog';

// #region Helper Badges
const PackagingBadge: React.FC<{
  code?: string;
  name?: string;
  id?: string;
}> = ({ code, name, id }) => {
  if (!code && !name && !id) return <span className="text-slate-400 italic">-</span>;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="font-semibold text-slate-800 text-xs">{name || id}</span>
      {code && <span className="text-[11px] text-slate-400 font-mono">{code}</span>}
    </div>
  );
};

const OrgBadge: React.FC<{
  code?: string;
  name?: string;
  id?: string;
}> = ({ code, name, id }) => {
  if (!code && !name && !id) return <span className="text-slate-400 italic">-</span>;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-slate-700 text-xs">{name || id}</span>
      {code && <span className="text-[10px] text-slate-400 font-mono">{code}</span>}
    </div>
  );
};

const EmpBadge: React.FC<{
  code?: string;
  name?: string;
  id?: string;
}> = ({ code, name, id }) => {
  if (!code && !name && !id) return <span className="text-slate-400 italic">-</span>;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-slate-700 text-xs font-medium">{name || id}</span>
      {code && <span className="text-[10px] text-slate-400 font-mono">{code}</span>}
    </div>
  );
};

const TeamBadge: React.FC<{
  code?: string;
  name?: string;
  id?: string;
}> = ({ code, name, id }) => {
  if (!code && !name && !id) return <span className="text-slate-400 italic">-</span>;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-slate-700 text-xs">{name || id}</span>
      {code && <span className="text-[10px] text-slate-400 font-mono">{code}</span>}
    </div>
  );
};

const OperationGroupBadge: React.FC<{
  code?: string;
  name?: string;
  id?: string;
}> = ({ code, name, id }) => {
  if (!code && !name && !id) return <span className="text-slate-400 italic">-</span>;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="font-semibold text-slate-800 text-xs">{name || id}</span>
      {code && <span className="text-[10px] text-slate-400 font-mono">{code}</span>}
