};

const OperationBadge: React.FC<{
  code?: string;
  name?: string;
  id?: string;
}> = ({ code, name, id }) => {
  if (!code && !name && !id) return <span className="text-slate-400 italic">-</span>;
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-slate-700 text-xs font-medium">{name || id}</span>
      {code && <span className="text-[10px] text-slate-400 font-mono">{code}</span>}
    </div>
  );
};
// #endregion

// #region Form Cell Components
const DeliveryPlanLocationFormCell: React.FC<{
  form: UseFormReturn<TDeliveryPlanForm>;
  idx: number;
}> = ({ form, idx }) => {
  const { t } = useTranslation(['deliveryPlan', 'address']);
  const [isAddressModalOpen, setIsAddressModalOpen] = useState(false);

  return (
    <FormField
      control={form.control}
      name={`details.${idx}.location` as FieldPath<TDeliveryPlanForm>}
      render={({ field }) => (
        <FormItem className="space-y-0">
          <FormControl>
            <div className="relative flex items-center">
              <Input
                {...field}
                value={(field.value as string) || ''}
                placeholder={t('deliveryPlan:placeholder.location', {
                  defaultValue: 'Địa điểm giao hàng...',
                })}
                className="h-8 text-xs bg-white pr-8 cursor-pointer hover:border-primary/50 transition-colors"
                onClick={() => setIsAddressModalOpen(true)}
              />
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsAddressModalOpen(true);
                }}
                className="absolute right-1.5 top-1/2 -translate-y-1/2 p-1 text-slate-400 hover:text-primary transition-colors cursor-pointer rounded"
                title={t('address:locationModal.title', { defaultValue: 'Chọn địa chỉ' })}
              >
                <MapPin className="h-3.5 w-3.5" />
              </button>
              {isAddressModalOpen && (
                <AddressPickerDialog
                  open={isAddressModalOpen}
                  onOpenChange={setIsAddressModalOpen}
                  title={t('deliveryPlan:placeholder.location', {
                    defaultValue: 'Địa điểm giao hàng',
                  })}
                  value={{
                    streetAddress: (field.value as string) || '',
                    fullAddress: (field.value as string) || '',
                  }}
                  onChange={(addr) => {
                    const formatted = addr.fullAddress || addr.streetAddress || '';
                    if (formatted) {
                      field.onChange(formatted);
                    }
                  }}
                />
              )}
            </div>
          </FormControl>
        </FormItem>
      )}
    />
  );
};

